import { Cache, Effect, Option } from "effect";
import type { HevyRequestOptions } from "@hevy-mcp/hevy-client";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import type {
	CacheObservationMetadata,
	CacheObservationScope,
	CacheObservationState,
	CacheObserver,
} from "./cache.js";
import { bucketCount } from "./result-telemetry.js";

export const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
export const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
export const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;
const EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE = 100;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

type TemplateListAllError = Effect.Error<
	ReturnType<TemplatesListAllOperation["effect"]>
>;

export type ExerciseTemplateCatalogCache = Cache.Cache<
	string,
	ExerciseTemplate[],
	TemplateListAllError
>;

export interface ExerciseTemplateCatalog {
	/**
	 * Effect-first catalog access for MCP resource and tool handlers.
	 *
	 * The server owns the cache passed to this catalog. Keeping this program
	 * Effect-valued lets the request handler decide where the one Promise
	 * collapse belongs.
	 */
	effect(
		options?: ExerciseTemplateCatalogOptions,
	): Effect.Effect<ExerciseTemplate[], TemplateListAllError>;
	/**
	 * Promise compatibility for callers that have not moved to the handler
	 * Effect boundary yet.
	 */
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
}

type CatalogOperations = {
	readonly templates?: {
		readonly listAll?: Pick<TemplatesListAllOperation, "effect">;
	};
};

function startObservation(
	observer: CacheObserver | undefined,
	state: CacheObservationState,
) {
	try {
		return observer?.start({ state });
	} catch {
		return undefined;
	}
}

function finishObservation(
	scope: CacheObservationScope | void,
	metadata?: CacheObservationMetadata,
): void {
	try {
		scope?.finish(metadata);
	} catch {
		// Cache observation is best-effort and cannot affect cache behavior.
	}
}

function notifyRefreshed(
	options: ExerciseTemplateCatalogOptions,
	catalog: ExerciseTemplate[],
	reason: ExerciseTemplateCatalogRefreshReason,
): void {
	try {
		options.onRefreshed?.(catalog, reason);
	} catch {
		// Cache callbacks are best-effort and cannot affect catalog behavior.
	}
}

function catalogPageCount(catalog: readonly ExerciseTemplate[]): number {
	const pages = (
		catalog as ExerciseTemplate[] & {
			readonly pageCount?: number;
		}
	).pageCount;
	if (pages !== undefined) return pages;
	return Math.max(
		1,
		Math.ceil(catalog.length / EXERCISE_TEMPLATE_CATALOG_PAGE_SIZE),
	);
}

/**
 * Build the catalog facade around one server-owned Effect Cache.
 *
 * `cache` is deliberately supplied by the server rather than constructed
 * here. This keeps cache lifetime at server/process scope instead of making it
 * request-local in `createToolRuntime` or `forExecution`.
 */
export function createExerciseTemplateCatalog(
	operations: CatalogOperations,
	cache: ExerciseTemplateCatalogCache,
	cacheObserver?: CacheObserver,
): ExerciseTemplateCatalog {
	const listAll = operations.templates?.listAll;
	if (!listAll) {
		throw new Error("Exercise template list operation is unavailable.");
	}
	let hasLoadedValue = false;
	let requestGeneration = 0;

	const getCacheState = Effect.fn("core.exerciseTemplateCatalog.cacheState")(
		function* () {
			const successful = yield* Cache.getSuccess(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			if (Option.isSome(successful)) {
				return "hit" as const;
			}
			const present = yield* Cache.has(
				cache,
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
			);
			return present
				? ("inflight_wait" as const)
				: hasLoadedValue
					? ("expired" as const)
					: ("miss" as const);
		},
	);

	const effect = Effect.fn("core.exerciseTemplateCatalog.get")(function* (
		options: ExerciseTemplateCatalogOptions = {},
	) {
		const refresh = options.refresh === true;
		const execution = options.execution;
		const observedState = refresh ? "refresh" : yield* getCacheState();
		const state =
			execution !== undefined && observedState === "inflight_wait"
				? "miss"
				: observedState;
		const observationScope = startObservation(cacheObserver, state);
		const reason: ExerciseTemplateCatalogRefreshReason =
			state === "refresh"
				? "explicit-refresh"
				: state === "expired"
					? "ttl-expired"
					: "initial-load";
		const sharedCacheLoad = state === "hit" || state === "inflight_wait";
		const bypassCache = refresh || (execution !== undefined && state !== "hit");
		const replaceSharedCacheLoad =
			observedState === "inflight_wait" && (refresh || execution !== undefined);
		const generation = sharedCacheLoad
			? requestGeneration
			: ++requestGeneration;
		const load = bypassCache
			? replaceSharedCacheLoad
				? Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY).pipe(
						Effect.flatMap(() =>
							execution === undefined
								? listAll.effect()
								: listAll.effect(execution),
						),
					)
				: execution === undefined
					? listAll.effect()
					: listAll.effect(execution)
			: Cache.get(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY);
		const shouldNotify = !sharedCacheLoad;
		let observationMetadata: CacheObservationMetadata | undefined;

		const observedLoad = load.pipe(
			Effect.tap((catalog) =>
				Effect.gen(function* () {
					if (!sharedCacheLoad && generation === requestGeneration) {
						hasLoadedValue = true;
					}
					if (bypassCache && generation === requestGeneration) {
						yield* Cache.set(
							cache,
							EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
							catalog,
						);
					}
					if (!sharedCacheLoad) {
						observationMetadata = {
							refreshReason: reason,
							pageCountBucket: bucketCount(catalogPageCount(catalog)),
							itemCountBucket: bucketCount(catalog.length),
						};
					}
					if (shouldNotify) {
						notifyRefreshed(options, catalog, reason);
					}
				}),
			),
			Effect.catch((error) =>
				Effect.flatMap(
					generation === requestGeneration
						? Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY)
						: Effect.void,
					() => Effect.fail(error),
				),
			),
		);

		const controlledLoad = execution
			? checkExecution(execution).pipe(Effect.flatMap(() => observedLoad))
			: observedLoad;

		return yield* Effect.ensuring(
			controlledLoad,
			Effect.sync(() => {
				finishObservation(observationScope, observationMetadata);
			}),
		);
	});

	return {
		effect,
		get(options) {
			return Effect.runPromise(effect(options));
		},
		reset() {
			hasLoadedValue = false;
			requestGeneration += 1;
			Effect.runSync(
				Cache.invalidate(cache, EXERCISE_TEMPLATE_CATALOG_CACHE_KEY),
			);
		},
	};
}

function checkExecution(execution: HevyRequestOptions) {
	return Effect.sync(() => {
		if (execution.signal?.aborted) {
			throw (
				execution.signal.reason ??
				new DOMException("Operation canceled", "AbortError")
			);
		}
		if (execution.deadline !== undefined && Date.now() >= execution.deadline) {
			throw new DOMException("Operation deadline exceeded", "TimeoutError");
		}
	});
}

import { Cache, Effect } from "effect";
import { TestClock } from "effect/testing";
import { describe, expect, it, vi } from "vitest";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import {
	createExerciseTemplateCatalog,
	type ExerciseTemplateCatalog,
	type ExerciseTemplateCatalogCache,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./exercise-template-catalog.js";

type ListAll = Pick<TemplatesListAllOperation, "effect">;
type ListAllError = Effect.Error<ReturnType<ListAll["effect"]>>;

function createCatalog(
	listAll: ListAll,
	cache?: ExerciseTemplateCatalogCache,
): ExerciseTemplateCatalog {
	const serverCache =
		cache ??
		Effect.runSync(
			Cache.make({
				capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
				timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
				lookup: (_key: string) => listAll.effect(),
			}),
		);
	return createExerciseTemplateCatalog({ templates: { listAll } }, serverCache);
}

function operation(effect: ListAll["effect"]): ListAll {
	return { effect };
}

describe("exercise template catalog", () => {
	it("reset clears the server cache and forces a fresh catalog request", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.succeed([{ id: "first" }]))
			.mockReturnValueOnce(Effect.succeed([{ id: "second" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "first" }]);
		catalog.reset();
		await expect(catalog.get()).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("deduplicates concurrent cache misses", async () => {
		let resolveLookup: ((templates: ExerciseTemplate[]) => void) | undefined;
		const listAll = vi.fn<ListAll["effect"]>().mockImplementation(() =>
			Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
				resolveLookup = (templates) => resume(Effect.succeed(templates));
			}),
		);
		const catalog = createCatalog(operation(listAll));

		const first = Effect.runPromise(catalog.effect());
		const second = Effect.runPromise(catalog.effect());
		await Promise.resolve();
		expect(listAll).toHaveBeenCalledOnce();

		resolveLookup?.([{ id: "shared", title: "Shared" }]);
		await expect(Promise.all([first, second])).resolves.toEqual([
			[{ id: "shared", title: "Shared" }],
			[{ id: "shared", title: "Shared" }],
		]);
	});

	it("does not share controlled calls between independently cancellable callers", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					const signal = options?.signal;
					if (signal?.aborted) {
						resume(Effect.fail(signal.reason));
						return;
					}
					const onAbort = () =>
						resume(Effect.fail(signal?.reason ?? new Error("aborted")));
					signal?.addEventListener("abort", onAbort, { once: true });
					const template =
						signal === firstController.signal ? "first" : "second";
					const timer = setTimeout(
						() => resume(Effect.succeed([{ id: template }])),
						template === "first" ? 100 : 20,
					);
					return Effect.sync(() => {
						clearTimeout(timer);
						signal?.removeEventListener("abort", onAbort);
					});
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		firstController.abort(new DOMException("first canceled", "AbortError"));

		await expect(first).rejects.toMatchObject({ name: "AbortError" });
		await expect(second).resolves.toMatchObject([{ id: "second" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("uses templates.listAll rather than a Promise client for lookup", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValue(
				Effect.succeed([{ id: "template-1", title: "Template 1" }]),
			);
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).resolves.toEqual([
			{ id: "template-1", title: "Template 1" },
		]);
		expect(listAll).toHaveBeenCalledOnce();
	});

	it("reloads after the five-minute TTL", async () => {
		let calls = 0;
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation(() =>
				Effect.succeed([{ id: `template-${++calls}` }]),
			);
		const catalog = createCatalog(operation(listAll));
		const program = Effect.gen(function* () {
			const first = yield* catalog.effect();
			yield* TestClock.adjust(
				`${EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS} millis`,
			);
			const second = yield* catalog.effect();
			return [first, second] as const;
		});

		await expect(
			Effect.runPromise(Effect.provide(program, TestClock.layer())),
		).resolves.toEqual([[{ id: "template-1" }], [{ id: "template-2" }]]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("invalidates a failed lookup before the next call", async () => {
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockReturnValueOnce(Effect.fail(new Error("temporary failure")))
			.mockReturnValueOnce(Effect.succeed([{ id: "recovered" }]));
		const catalog = createCatalog(operation(listAll));

		await expect(catalog.get()).rejects.toThrow("temporary failure");
		await expect(catalog.get()).resolves.toMatchObject([{ id: "recovered" }]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});

	it("does not let an older controlled load replace a newer result", async () => {
		const firstController = new AbortController();
		const secondController = new AbortController();
		const pending: Array<{
			signal: AbortSignal | undefined;
			resume: (effect: Effect.Effect<ExerciseTemplate[]>) => void;
		}> = [];
		const listAll = vi
			.fn<ListAll["effect"]>()
			.mockImplementation((options?: HevyExecutionOptions) =>
				Effect.callback<ExerciseTemplate[], ListAllError>((resume) => {
					pending.push({ resume, signal: options?.signal });
				}),
			);
		const catalog = createCatalog(operation(listAll));

		const first = catalog.get({
			execution: { signal: firstController.signal },
		});
		const second = catalog.get({
			execution: { signal: secondController.signal },
		});
		await vi.waitFor(() => expect(pending).toHaveLength(2));

		pending[1]?.resume(Effect.succeed([{ id: "newer" }]));
		await expect(second).resolves.toMatchObject([{ id: "newer" }]);
		pending[0]?.resume(Effect.succeed([{ id: "older" }]));
		await expect(first).resolves.toMatchObject([{ id: "older" }]);
		await expect(catalog.get()).resolves.toMatchObject([{ id: "newer" }]);
		expect(pending.map(({ signal }) => signal)).toEqual([
			firstController.signal,
			secondController.signal,
		]);
		expect(listAll).toHaveBeenCalledTimes(2);
	});
});

import type { ResultCountBucket } from "./result-telemetry.js";

export type CacheObservationState =
	| "hit"
	| "miss"
	| "refresh"
	| "expired"
	| "inflight_wait";

export interface CacheObservationMetadata {
	readonly refreshReason?: "explicit-refresh" | "initial-load" | "ttl-expired";
	readonly pageCountBucket?: ResultCountBucket;
	readonly itemCountBucket?: ResultCountBucket;
}

export interface CacheObservation extends CacheObservationMetadata {
	readonly state: CacheObservationState;
}

export interface CacheObservationScope {
	finish(metadata?: CacheObservationMetadata): void;
}

export interface CacheObserver {
	start(observation: CacheObservation): CacheObservationScope | void;
}

export interface AsyncCacheOptions {
	ttlMs: number;
	maxSize: number;
	observer?: CacheObserver;
}

export interface CacheGetOptions {
	refresh?: boolean;
	/** Controlled callers must not share an in-flight request they can cancel. */
	shareInFlight?: boolean;
	signal?: AbortSignal;
	deadline?: number;
	getObservationMetadata?: () => CacheObservationMetadata | undefined;
}

import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { Cache, Effect, Exit, Schema, Scope } from "effect";
import { createOperations } from "@hevy-mcp/operations";
import type { ExerciseTemplate } from "@hevy-mcp/hevy-client/types";
import type { TemplatesListAllOperation } from "@hevy-mcp/operations";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import {
	createExerciseTemplateCatalog,
	EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
	EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
} from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
import { mergeAbortSignals } from "./execution.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
}

/** A safe construction failure raised before an MCP server is exposed. */
export class HevyMcpServerConstructionError extends Schema.TaggedError<HevyMcpServerConstructionError>()(
	"HevyMcpServerConstructionError",
	{ message: Schema.String },
) {}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

/**
 * Construct a server in a caller-owned Scope.
 *
 * Keeping this as an Effect makes the lifetime of the catalog explicit. The
 * Promise façade below opens a Scope and attaches its release to `close()`.
 */
export const createHevyMcpServerEffect = Effect.fn("core.createHevyMcpServer")(
	function* (
		options: CreateHevyMcpServerOptions,
	): Effect.fn.Return<McpServer, HevyMcpServerConstructionError, Scope.Scope> {
		const baseServer = new McpServer(
			{ name: SERVER_NAME, version: SERVER_VERSION },
			{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
		);
		const server = options.decorateServer?.(baseServer) ?? baseServer;
		const mcpLogger = createMcpClientLogger(server);
		const client = options.createClient({ onLog: (event) => mcpLogger(event) });
		const operations = createOperations(client);
		const templateListAll = operations.templates?.listAll;
		if (!templateListAll) {
			return yield* new HevyMcpServerConstructionError({
				message: "Exercise template list operation is unavailable.",
			});
		}
		const shutdown = new AbortController();
		const lifecycleSignal = options.lifecycleSignal
			? mergeAbortSignals(options.lifecycleSignal, shutdown.signal)
			: shutdown.signal;
		const cache = yield* Cache.make<
			string,
			ExerciseTemplate[],
			Effect.Error<ReturnType<TemplatesListAllOperation["effect"]>>
		>({
			capacity: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
			timeToLive: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
			lookup: (_key: string) => templateListAll.effect(),
		});
		yield* Effect.addFinalizer(() => {
			shutdown.abort(new DOMException("Server closed", "AbortError"));
			return Cache.invalidateAll(cache);
		});
		const runtime = createToolRuntime({
			client,
			operations,
			catalog: createExerciseTemplateCatalog(
				operations,
				cache,
				options.cacheObserver,
			),
			logger: mcpLogger,
			observer: options.observer,
			executionTimeoutMs: options.executionTimeoutMs,
			executionDeadline: options.executionDeadline,
			lifecycleSignal,
		});
		const counting = createCountingServer(server);
		registerHevyTools(counting.server, runtime);
		options.onToolsRegistered?.(counting.getCount());
		registerWorkoutPrompts(server, options.observer);
		registerHevyResources(server, runtime);
		return server;
	},
);

export function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): McpServer {
	const scope = Effect.runSync(Scope.make());
	const server = Effect.runSync(
		Scope.provide(scope)(createHevyMcpServerEffect(options)),
	);
	const close = server.close.bind(server);
	let closePromise: Promise<void> | undefined;
	server.close = async () => {
		closePromise ??= (async () => {
			try {
				await close();
			} finally {
				await Effect.runPromise(Scope.close(scope, Exit.succeed(undefined)));
			}
		})();
		await closePromise;
	};
	return server;
}

